// DeleteCalendar queues a soft delete. A record already deleted or gone is
// not an error: two batches deleting the same record must not fail each other.
func (b *gormBatch) DeleteCalendar(name string) {
	r := &GormCalendarRepository{DB: b.db}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueCalendarDelete(b.u, name, false)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.markDeleted(ctx, tx, key).Error
	})
	b.u.Record(repox.Change{Type: "calendar.acme.example/Calendar", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getCalendar)})
}

// PurgeCalendar queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) PurgeCalendar(name string) {
	// A record something still refers to is kept, as Purge keeps it.
	r := &GormCalendarRepository{DB: b.db, Refs: b.u.Conn().References}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	keep := queueCalendarPurge(b.u, name)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		if *keep {
			return nil
		}
		if _, err := r.purge(ctx, tx, key, name, false); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}
		return nil
	})
	b.u.Record(repox.Change{Type: "calendar.acme.example/Calendar", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getCalendar)})
}

